use rivet::{config::ProviderConfig,domain::*,model_pool::*};
const M:u64=1024*1024;
fn profile(id:&str,instance:&str,slots:u32)->Profile{let mut p=Profile{id:id.into(),provider:ProviderConfig{profile:"llama.cpp-compatible".into(),endpoint:"http://127.0.0.1:1/v1/chat/completions".into(),model:"synthetic".into(),context_tokens:Some(65536)},instance:instance.into(),resident:true,remote:false,weights_ram:128*M,weights_vram:0,kv_ram_per_token:16,kv_vram_per_token:0,slots,loading_ram:64*M,loading_vram:0,qualification:None};if slots>1{p.qualification=Some(Qualification{profile_digest:p.digest().unwrap(),evidence_sha256:"a".repeat(64),owner_statement:"Explicit synthetic fixture capacity declaration; no real model measured".into()});}p}
fn policy(behavior:Behavior,slots:u32)->Policy{Policy{adaptive:None,schema_version:1,behavior,limits:Limits{ram:2*1024*M,vram:0,os_ram:256*M,tools_ram:1024*M,browser_ram:0,loading_overlap_ram:32*M,loading_overlap_vram:0},profiles:vec![profile("shared","instance-a",slots)],assignments:vec!["shared".into(),"shared".into()],phases:vec![]}}
#[test]
fn shared_weights_kv_slots_owner_qualification_and_unknown_holds_are_bounded(){
    let mut state=State::new(policy(Behavior::Shared,1),1,2,2).unwrap();let actor=ActorId::default();let request=RequestId::default();let(base,_)=state.usage().unwrap();state.reserve(request,actor,0,0,"shared",100).unwrap();assert_eq!(state.usage().unwrap().0,base+1600);assert!(state.reserve(RequestId::default(),ActorId::default(),1,1,"shared",100).is_err());state.settle(request,false).unwrap();state.fence(2);assert!(state.reservations[0].unknown);assert!(!state.eligible(ActorId::default(),1,1));state.settle(request,true).unwrap();assert_eq!(state.usage().unwrap().0,base);
    let mut state=State::new(policy(Behavior::Concurrent,2),1,2,2).unwrap();let a=ActorId::default();state.reserve(RequestId::default(),a,0,0,"shared",100).unwrap();assert!(state.reserve(RequestId::default(),a,0,0,"shared",100).is_err());state.reserve(RequestId::default(),ActorId::default(),1,1,"shared",200).unwrap();assert_eq!(state.usage().unwrap().0,base+4800);assert_eq!(state.reservations.len(),2);
    let mut invalid=policy(Behavior::Concurrent,2);invalid.profiles[0].provider.model="changed".into();assert!(invalid.validate(2,2).is_err());invalid=policy(Behavior::Concurrent,2);invalid.profiles[0].qualification=None;assert!(invalid.validate(2,2).is_err());invalid=policy(Behavior::Shared,1);invalid.profiles[0].provider.context_tokens=None;assert!(invalid.validate(2,2).is_err());
}
#[test]
fn relay_loading_overlap_approval_observation_and_serial_phase_fencing(){
    let mut p=policy(Behavior::Relay,1);let mut target=profile("next","instance-b",1);target.resident=false;target.weights_ram=256*M;p.profiles.push(target);p.phases=vec![Phase{tasks:vec![0],profile:"next".into(),goal:PhaseGoal::Succeeded}];let mut state=State::new(p,1,2,2).unwrap();let proposal=state.phase_proposal().unwrap();assert!(state.approve_phase("wrong",vec![]).is_err());state.approve_phase(&digest(&proposal).unwrap(),vec!["artifact-ref".into()]).unwrap();assert!(state.activation.is_some());assert!(!state.eligible(ActorId::default(),0,0));assert!(state.observe_activation(&digest(&proposal).unwrap(),false,true,&"b".repeat(64)).is_err());state.fence(2);assert!(state.activation.is_some());state.observe_activation(&digest(&proposal).unwrap(),true,true,&"b".repeat(64)).unwrap();assert!(!state.policy.profiles[0].resident);assert!(state.policy.profiles[1].resident);assert!(state.eligible(ActorId::default(),0,0));let actor=ActorId::default();state.reserve(RequestId::default(),actor,0,0,"next",100).unwrap();assert!(!state.eligible(ActorId::default(),1,0));
    let mut p=policy(Behavior::Relay,1);let mut target=profile("next","instance-b",1);target.resident=false;target.weights_ram=1024*M;p.profiles.push(target);p.phases=vec![Phase{tasks:vec![0],profile:"next".into(),goal:PhaseGoal::Succeeded}];let mut state=State::new(p,1,2,2).unwrap();let proposal=state.phase_proposal().unwrap();assert!(state.approve_phase(&digest(&proposal).unwrap(),vec![]).is_err());assert!(state.activation.is_none());
}
#[test]
fn cookbook_imports_qualified_cli_shape_ignores_commands_and_ranks_whole_allocations(){
    let input=serde_json::json!({"system":{"total_ram_gb":64},"models":[{"name":"synthetic","usable_context":65536,"effective_context_length":8192,"score":80,"estimated_tps":50,"installed":true,"runtime":"llama.cpp","capability_ids":["tool_use"],"total_memory_gb":0.1,"verify_command":"MUST NEVER EXECUTE","gguf_sources":["https://example.invalid/model"]}]});let bytes=serde_json::to_vec(&input).unwrap();let catalog=rivet::cookbook::import("1.1.17",&bytes).unwrap();assert!(rivet::cookbook::import("unknown",&bytes).is_err());for preference in [rivet::cookbook::Preference::Efficient,rivet::cookbook::Preference::Balanced,rivet::cookbook::Preference::Ambitious]{let mut impossible=policy(Behavior::Concurrent,2);impossible.profiles[0].weights_ram=4*1024*M;let ranking=rivet::cookbook::rank(&catalog,&[impossible,policy(Behavior::Shared,1)],2,2,preference).unwrap();assert!(ranking[0].feasible);assert!(!ranking[1].feasible);assert!(ranking[0].reasons.iter().any(|r|r.contains("counted once")));}
}
